behavior:
// Box Spawner — a hopper that emits cargo boxes. Demonstrates ctx.spawn: the behavior runs its own rate
// timer and emits a box every 60/boxesPerMinute seconds; the host creates the dynamic cargo body at the
// part's pose + the given local offset. Cargo drops at the exact spawn point (no positional scatter), so
// downstream handling (picks, aligned queues) sees a repeatable pose. A pilot "Use" toggles the feed (a
// runtime latch, so it resets on stop/reload). Optionally gated by a conveyor interlock
// (conveyorId → ctx.conveyorRunning) or a PLC run tag.
//
// A hopper is PACED, not commanded: what the author sets is the INTERVAL BETWEEN boxes, so that is what a hold
// preserves. The countdown therefore keeps running while the gate is shut but floors at zero — a hold neither
// costs a period nor banks one. Freeze it instead and every release pays out the remainder of an interval the
// hopper spent standing still (in the PLC demo: ~2.7 s of empty lane at the top of every row); let it run
// unfloored and a long hold banks a burst that all lands in one tick.
// This is the opposite rule from the pallet spawner, deliberately: a MAGAZINE is commanded, so it re-arms on
// every enable and drops at once, which is what makes a sub-period command pulse dispense exactly one.

// random-size range, full box dimensions (m)
const SIZE_MIN = [0.4, 0.3, 0.3]
const SIZE_MAX = [0.8, 0.5, 0.5]

let countdown = 0 // seconds until the next spawn
let started = false // arm the first box on the first eligible tick
let colorIndex = 0
let usedOff = false
let spawned = 0

// Publish what this feed has dispensed, every tick (a display not republished goes blank): the infeed half
// of the line's numbers, which a despawner's count is the other half of - the two differ by the work in
// progress. It counts REQUESTS: past the physics engine's 10,240-body table a spawn is skipped, uncounted
// by the host but still counted here.
function publish(ctx) {
  ctx.display('spawned', spawned)
  if (ctx.params.enableComms && ctx.params.countTag) ctx.writeNumber(ctx.params.countTag, spawned)
}

// parse "#rrggbb" → [r, g, b] in 0..1
function hexRgb(hex) {
  const h = (hex || '').replace('#', '')
  if (h.length < 6) return [1, 1, 1]
  const v = (i) => { const n = parseInt(h.slice(i, i + 2), 16); return Number.isFinite(n) ? n / 255 : 1 }
  return [v(0), v(2), v(4)]
}
// parse a comma-separated hex list → [[r,g,b], …]
function palette(csv) {
  return (csv || '').split(',').map((c) => c.trim()).filter((c) => c.length >= 6).map(hexRgb)
}

definePart({
  interactive: true, // a pilot "Use" toggles the feed
  params: {
    boxesPerMinute: { type: 'number', unit: '/min', default: 45, min: 0, max: 1000, step: 1, label: 'Feed rate', desc: 'Boxes per minute. 0 halts the feed without pausing the part, so the timer restarts cleanly when you raise it again.' },
    fixedRate: { type: 'boolean', default: true, label: 'Fixed rate (off = ±50% jitter)', desc: 'On, boxes arrive on an exact metronome. Off, each gap is randomised between half and one-and-a-half times the nominal period, which is what an untidy real feed looks like downstream.' },
    boxColor: { type: 'color', default: '#cc8844', label: 'Box color', group: 'Box', desc: 'Tint for every spawned box. Ignored once the cycle list below is non-empty.' },
    boxColors: { type: 'color', list: true, default: '', label: 'Box colors (cycle)', group: 'Box', desc: 'Colors handed out one per box, in order, overriding the single color above. Useful for telling sorted lanes apart at a glance. Leave empty to use the single colour.' },
    randomColors: { type: 'boolean', default: false, label: 'Random color order', group: 'Box', desc: 'Draw each colour at random from the cycle list instead of walking the list in order.' },
    length: { type: 'number', default: 0.6, min: 0.1, step: 0.05, label: 'Box length (m)', group: 'Box', desc: 'Extent along local X of each spawned box. Ignored while Random size is on.' },
    width: { type: 'number', default: 0.4, min: 0.1, step: 0.05, label: 'Box width (m)', group: 'Box', desc: 'Extent along local Z of each spawned box. Ignored while Random size is on.' },
    height: { type: 'number', default: 0.4, min: 0.1, step: 0.05, label: 'Box height (m)', group: 'Box', desc: 'Extent along local Y of each spawned box. Ignored while Random size is on.' },
    randomSize: { type: 'boolean', default: false, label: 'Random size', group: 'Box', desc: 'Give each box a random size and IGNORE the three dimensions above. The random range is fixed by the part (0.4-0.8 long, 0.3-0.5 high, 0.3-0.5 wide), not derived from them.' },
    mass: { type: 'number', default: 10, min: 0.5, max: 100, step: 0.5, label: 'Mass (kg)', group: 'Box', desc: 'Mass given to every spawned box, whatever its size.' },
    disable: { type: 'boolean', default: false, label: 'Paused', desc: 'Stop spawning entirely. Use (C, or E while walking) is a separate hand stop: it pauses and resumes the feed during a run without changing this setting, and is cleared when the run stops.' },
    keepSpacing: { type: 'boolean', default: false, label: 'Keep spacing while held', desc: 'Hold the interval while the feed is held instead of letting it run down, so boxes dropped onto a conveyor that stops with this spawner (give both the same run tag) stay one pitch apart however often the pair stops.' },
    conveyorId: { type: 'partRef', default: '', label: 'Pause when conveyor stopped', desc: 'Interlock: while the named conveyor is stopped, this spawner holds. Wire that conveyor to the PLC and the feed gates itself, with no tag of its own.' },
    enableComms: { type: 'boolean', default: false, label: 'Enable comms', group: 'Comms', desc: 'Connect this part to a PLC program. Its tags appear once this is on.' },
    runTag: { type: 'tag', dir: 'in', stType: 'BOOL', default: '', label: 'Run tag (spawn only while true)', group: 'Comms', desc: 'Gate the feed from the program. Note this only takes over once a program actually DRIVES the tag - until then the spawner keeps running, so a merely-declared tag is not a stopped feed.' },
    countTag: { type: 'tag', dir: 'out', stType: 'DINT', default: '', label: 'Spawned count tag', group: 'Comms', desc: 'Running total of boxes this spawner has dispensed. Subtract the despawner counts to get the work in progress.' },
  },
  step(ctx) {
    const p = ctx.params
    if (ctx.used()) usedOff = !usedOff
    // hold while a linked conveyor is stopped, or while a controller DRIVES the run tag de-energized
    // (ctx.tagDriven = output ownership; gating on the tag NAME alone would stop the spawner the moment one
    // was typed).
    const stopped = !ctx.conveyorRunning(p.conveyorId) || (p.enableComms && ctx.tagDriven(p.runTag) ? !ctx.readTag(p.runTag) : false)
    if (p.disable || usedOff || stopped || p.boxesPerMinute <= 0) {
      // held: the interval runs on, floored at zero — see the note at the top. Floored is what makes this safe
      // for an interlock that STUTTERS: at most one box is ever due when the gate reopens, never a burst.
      // Keep spacing: a feed onto a conveyor that stops WITH it (the same gate) must not run its interval down, or
      // the first box after a hold lands on the one the stopped belt is still holding under the drop
      if (!p.keepSpacing) countdown = Math.max(0, countdown - ctx.dt)
      publish(ctx)
      return
    }
    const period = 60 / p.boxesPerMinute
    // the first box drops on the first eligible tick, not after a full period
    if (!started) { started = true; countdown = 0 }
    countdown -= ctx.dt
    const pal = palette(p.boxColors)
    let n = 0
    while (countdown <= 0 && n < 8) {
      countdown += p.fixedRate ? period : Math.max(ctx.dt, period * (0.5 + ctx.rng()))
      n++
      let color
      if (pal.length > 0) {
        color = p.randomColors ? pal[Math.floor(ctx.rng() * pal.length)] : pal[colorIndex % pal.length]
        colorIndex++
      } else {
        color = hexRgb(p.boxColor)
      }
      const rnd = (i) => SIZE_MIN[i] + ctx.rng() * (SIZE_MAX[i] - SIZE_MIN[i])
      const size = p.randomSize ? [rnd(0), rnd(1), rnd(2)] : [p.length, p.height, p.width]
      ctx.spawn({ size: size, color: color, mass: p.mass, offset: [0, -0.2, 0] })
      spawned++
    }
    publish(ctx)
  },
})
